SELECT id, customer_id, order_date, status, amount, MIN(discount) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_discount, COUNT(discount) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_discount, SUM(discount) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_discount, LAG(discount, 1) OVER (PARTITION BY status, channel ORDER BY order_date, id) AS prev_discount FROM orders
